-- P06 The Pivot - Stage 2 (subject heading, not a page or a loan length)
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Stack Reference Card - Field Record","dataPayload":"STACK REFERENCE DESK. A single index card sits in the drawer, older than the cards around it. Three fields are filled in by hand. FIELD ONE is a call mark. FIELD TWO is headed PIVOT and carries a stamped numeral in the older roman style: XVII. FIELD THREE is headed TERM and is blank. A small cross-stamp sits in the corner: RECORDED AGAINST SUBJECT HEADING.","visualType":"observation","whatTheySee":"An old index card with a call mark, a roman-numeral pivot, a blank term field, and a subject cross-stamp.","taskPrompt":"Record all three fields and the corner cross-stamp exactly as they are written. Do not yet decide what the pivot means.","intermediateOutput":"Three fields recorded; the pivot is stamped in the older roman style and cross-stamped to a subject heading."},"analyst":{"role":"ANALYST","screenTitle":"Subject Register - Field Comparison","dataPayload":"SUBJECT REGISTER, card catalogue index. Headings are written in ARABIC numerals and the field is always named PIVOT. PAGE citations use the field PAGE. A loan length uses the field TERM and is written in weeks. The register lists 96 subject headings; the programme files name fewer than 20 researchers.","visualType":"document-forensics","whatTheySee":"The register shows that PIVOT is its own field name for a subject heading, and that the register writes headings in modern numerals.","taskPrompt":"Decide which of the three candidate readings - a page, a subject heading, a loan length - the card PIVOT field belongs to. Then convert the old-style numeral into the notation this register uses.","intermediateOutput":"The pivot is a subject heading; the card carries it in the older style and the register writes headings in the modern style."},"operator":{"role":"OPERATOR","screenTitle":"Reference Desk Terminal - Subject Query","dataPayload":"REFERENCE DESK TERMINAL. This terminal keys only to SUBJECT HEADINGS; a page query and a term query are both refused by the desk grant. Last queries filed by L. Veyr. Enter the subject heading the card points at, in the notation the register uses.","visualType":"meta","whatTheySee":"A terminal that accepts subject headings and refuses page or term queries.","taskPrompt":"Enter the two-digit subject heading.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The desk terminal grant and its log: the terminal refuses PAGE and TERM queries and accepts only SUBJECT HEADINGS, and the last queries were filed by L. Veyr. This is what settles that the card pivot is a subject key and not a page or a loan length.","operatorTaskDescription":"Hold the reference desk terminal. You are the only role who can query the index, and the terminal will accept only a subject heading, so the team must settle the field before you type. Report nothing yourself; take the value from the Observer and the Analyst once they agree."},"coordinationChain":{"observerProduces":"The Observer reports the three fields and the roman-style pivot stamp.","analystTransforms":"The Analyst shows that PIVOT is the field name of the subject register and converts the old-style numeral into the register notation.","operatorExecutes":"The Operator, whose terminal accepts only subject headings, files the subject heading."},"hints":["Three readings fit the card: a page, a subject heading, a loan length. Settle which field the pivot is before you read its value.","PAGE and TERM are the register own field names for a page and for a loan length. Which field name does this card print above the numeral?","The pivot is a subject heading, and the card writes it in the older numeral style. Convert it into the register notation and it is ready to file."],"narrativeObjective":"Establish what the archive means by a pivot before reading its value.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"17","validationMethod":"exact","fullSolution":"The card prints PIVOT, the field name of the subject register, so the value is neither a page nor a loan length. The old-style numeral converts to the subject heading 17."}',
  metadata = '{"type":"MEMORY","difficulty":2,"time":"5m","storyReveal":"The archive indexes the programme by subject rather than by page or loan: the pivot field recurs on every later record, and the register holds far more subject headings than the file names researchers - the programme had more subjects than names.","locationClue":{"format":"Map Marker","clueText":"LINA''S NOTE: \"The library basement contains a server rack with blinking binary LEDs.\"","solution":"Library Basement Server Rack","nextPhysicalLocation":"[LIBRARY] - Basement Server Rack","nextQrNode":"QR-NODE-07","explanation":"Points to the library basement server rack."},"evidenceUnlocked":{"id":"EVID-P06","category":"Document","title":"Stack Reference Card - Subject Pivot","state":"RECOVERED","timestamp":"Stage 2","source":"Library stack reference desk","content":"An old catalogue card whose PIVOT field cross-stamps it to the subject register. The register holds 96 subject headings for a programme that files fewer than 20 researchers."},"whyTeamworkMatters":"Only the card shows the pivot was stamped; only the register says what a pivot is; only the desk terminal shows the archive permits subject queries alone.","feeds":"M01"}'
WHERE code = 'P06';

-- P07 The Binary - Stage 2 (a wall-clock stamp, not a checksum or a corrected stamp)
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Service Tape - Field Record","dataPayload":"BASEMENT SERVER RACK. A service tape spools out of the rack, punched on four channels. Its header block prints four labelled fields. EPOCH MARKER: rack time base, archive sync feed. DATA: two pairs, punched as ONE-SEVEN then FOUR-SEVEN. MIRROR: the same digits re-stamped after an offset; the offset digits are worn and cannot be read. PARITY: a single byte, ONE.","visualType":"observation","whatTheySee":"A punched service tape with an epoch marker, a two-pair data field, a worn mirror offset, and a parity byte.","taskPrompt":"Record the header fields and the data field pair by pair, exactly as punched.","intermediateOutput":"Data field recorded as two pairs; the epoch marker declares the rack time base; parity is a single byte; the mirror offset is unreadable."},"analyst":{"role":"ANALYST","screenTitle":"Service Log - Field Rules","dataPayload":"THE FIELD RULES THE TAPE PRINTS ON ITS OWN REVERSE. A field is a WALL-CLOCK STAMP when the epoch marker is set on it; it is a CHECK VALUE when the parity byte is the last field; it is a CORRECTED STAMP when the mirror column carries an offset. Only one field on this tape carries the epoch marker. The mirror offset is worn, so the corrected reading cannot be computed from the tape alone.","visualType":"document-forensics","whatTheySee":"The field rules the tape carries, which tie the data field to the epoch marker.","taskPrompt":"Use the field rules to decide whether the data field is a wall-clock stamp, a checksum, or a corrected stamp. Then assemble the hour and the minute in the order the field prints them.","intermediateOutput":"The data field is a wall-clock stamp under the epoch marker; the parity byte is the checksum candidate; the mirror is the corrected-stamp candidate but the offset is unreadable."},"operator":{"role":"OPERATOR","screenTitle":"Rack Console - Time Base Authority","dataPayload":"RACK CONSOLE. This console holds the rack time base. It refuses a checksum entry and refuses a mirror entry; it accepts one wall-clock stamp in HH:MM. Console note: the rack was driven by the archive sync feed, and every machine-readable record in the building is stamped from that feed. Enter the wall-clock stamp the data field carries.","visualType":"meta","whatTheySee":"A console that accepts only a wall-clock stamp in HH:MM.","taskPrompt":"Enter the wall-clock stamp in HH:MM.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The rack console and its time-base grant: the console refuses checksum and mirror entries and accepts one wall-clock stamp, and its note records that every machine-readable record in the building is stamped from the same archive sync feed. This is what establishes that the data field is a time of day.","operatorTaskDescription":"Hold the rack console. Your grant fixes the format as HH:MM and rejects any other reading, so the team must agree on the field before you type. You are also the only role who can read the console note about the sync feed; report it so the Analyst can weigh the corrected-stamp candidate."},"coordinationChain":{"observerProduces":"The Observer records the header fields and the data field as two pairs.","analystTransforms":"The Analyst applies the field rules: the epoch marker makes the data field a wall-clock stamp and the parity byte the checksum candidate.","operatorExecutes":"The Operator, whose console accepts only a wall-clock stamp in HH:MM, enters the stamp."},"hints":["Three readings fit the data field: a wall-clock time, a corrected time, a checksum. Match each against the field rules before choosing.","The epoch marker sits on the data field alone; the parity byte is a single byte and the mirror column carries a worn offset.","The field that carries the epoch marker is the wall-clock stamp. Read its two pairs in the order they are punched and the hour and the minute are settled."],"narrativeObjective":"Decide what kind of value the service log carries before reading it.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"17:47","validationMethod":"exact","fullSolution":"The epoch marker sits on the data field, so the field rules make it a wall-clock stamp rather than a checksum or the mirror corrected reading. The two punched pairs read as the hour and the minute, giving 17:47."}',
  metadata = '{"type":"BINARY","difficulty":3,"time":"8m","storyReveal":"The service log is a time record, not an infrastructure log: the rack that held the programme records was driven by the archive sync feed, and every machine-readable record in the building is stamped from it.","locationClue":{"format":"Document","clueText":"LINA''S NOTE: \"Return to the archive. Check the 2021 project folder in cabinet 3.\"","solution":"Archive Cabinet 3","nextPhysicalLocation":"[ADMIN BUILDING] - Archive Cabinet 3","nextQrNode":"QR-NODE-08","explanation":"Points back to the archive cabinet."},"evidenceUnlocked":{"id":"EVID-P07","category":"Document","title":"Service Log Extract - Rack Time Base","state":"RECOVERED","timestamp":"Stage 2","source":"Library basement server rack","content":"The tape header shows the rack time base came from the archive sync feed and that every machine-readable record in the building is stamped from the same feed. The tape was filed by L. Veyr in a programme folder, not an infrastructure folder."},"whyTeamworkMatters":"Only the tape shows the punched pairs; only the field rules say which field is a time; only the console holds the time-base grant and the note about the sync feed.","feeds":"P06"}'
WHERE code = 'P07';

-- P08 The Vector - Stage 2 (a vault label, not a name or a bearing)
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Access Plate - Field Record","dataPayload":"ARCHIVE CABINET 3. An access plate is bolted to the cabinet door and carries a single Greek letter, worn at the centre. Beside the cabinet a key card is mounted, listing five positions in a Greek series: ONE is ALPHA, TWO is BETA, THREE is GAMMA, FOUR is worn smooth, FIVE is EPSILON. The plate letter sits at the fourth position.","visualType":"observation","whatTheySee":"An access plate with a worn Greek letter, beside a key card of five Greek-named positions.","taskPrompt":"Record the plate mark and the position it occupies in the key card series.","intermediateOutput":"A Greek letter at position four of a five-position series; the name at that position is worn off the key card."},"analyst":{"role":"ANALYST","screenTitle":"Vault Index - Series Comparison","dataPayload":"VAULT INDEX, mounted in the corridor. It lists rooms in the same five-position series: 01 intake room, 02 records room, 03 clock room, 04 a restricted room whose label is worn, 05 transfer room. Personal names are filed in a different index, alphabetically. Compass bearings are filed on the survey sheet. This index is a ROOM register, and each room is keyed by its position in the series.","visualType":"document-forensics","whatTheySee":"A corridor index that keys five rooms by the same Greek series positions.","taskPrompt":"Decide whether the plate mark is a person, a movement direction, or a vault label. Then supply the letter-name the series uses at the mark position.","intermediateOutput":"The mark is a vault label; the series names its positions with the older Greek letter-names, and the fourth name is the one worn off the key card."},"operator":{"role":"OPERATOR","screenTitle":"Archive Access Register - Vault Label","dataPayload":"ARCHIVE ACCESS REGISTER. The register confers VAULT LABELS only, keyed by position in the Greek series; it refuses personal names and it refuses bearing entries. Enter the vault label for position four, written as the series writes it, in capitals.","visualType":"meta","whatTheySee":"A register that confers vault labels by series position and refuses names and bearings.","taskPrompt":"Enter the vault label in capitals.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The archive access register: it confers VAULT LABELS by series position and refuses both personal names and compass bearings. That refusal is what makes the plate a room designation rather than a person or a direction.","operatorTaskDescription":"Hold the archive access register. It accepts a vault label for a series position and nothing else, so the team must rule out the name and the bearing before you type. Take the letter-name from the Analyst once the series position is agreed."},"coordinationChain":{"observerProduces":"The Observer reports the worn plate letter and its position in the five-position series.","analystTransforms":"The Analyst shows the corridor index keys rooms by series position and supplies the series letter-name at that position.","operatorExecutes":"The Operator, whose register confers vault labels only, enters the vault label."},"hints":["Three readings fit the mark: a person, a movement direction, a vault label. Establish which register the mark belongs to before naming it.","Personal names are filed alphabetically; bearings are filed on the survey sheet; this mark sits in a series of rooms.","The worn position in the series is a room, and the series names its positions with the older Greek letter-names. Supply the letter-name for the fourth position; that name is the vault label."],"narrativeObjective":"Decide what kind of designation the mark is before naming it.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"DELTA","validationMethod":"exact","fullSolution":"The mark is a vault label, not a name or a bearing: the vault index keys rooms by position in the Greek series and names position four with a letter-name. The fourth Greek letter is DELTA."}',
  metadata = '{"type":"PATTERN","difficulty":3,"time":"7m","storyReveal":"The vaults are keyed to a numbered Greek series that runs past the named rooms, and one position in the series has been deliberately worn smooth - the building record treats the programme locations as a lattice of labelled positions rather than a set of rooms with names.","locationClue":{"format":"Numerical","clueText":"LINA''S NOTE: \"Follow the corridor to the room of clocks. The face you want is not on the wall.\"","solution":"Clock Room","nextPhysicalLocation":"[ADMIN BUILDING] - Clock Room","nextQrNode":"QR-NODE-09","explanation":"Points to the clock room."},"evidenceUnlocked":{"id":"EVID-P08","category":"Visual","title":"Vault Index Plate","state":"RECOVERED","timestamp":"Stage 2","source":"Archive cabinet 3 corridor","content":"A corridor index listing vault rooms in a numbered Greek series; one position label has been filed smooth. The index is a room register, not a personnel list."},"whyTeamworkMatters":"Only the plate shows the worn mark; only the index shows the series is rooms; only the register shows the institution confers vault labels by position.","feeds":"P07"}'
WHERE code = 'P08';

-- P09 The Chronology - Stage 2 (a real unfiled transfer, numbered 17)
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Custody Board - Entry Record","dataPayload":"CLOCK ROOM. A custody board lists transfers in a numbered run. The visible numbers are 14, 15, 16, 18, 19; one slot between 16 and 18 is blank. Each entry carries two stamps, RECEIVED and RELEASED, and each stamp carries a minute reading.","visualType":"observation","whatTheySee":"A numbered custody run with one blank slot and two time stamps per entry.","taskPrompt":"Record the numbered run exactly, and note which slot is blank.","intermediateOutput":"Run recorded with one slot blank between 16 and 18; every entry carries a received stamp and a released stamp."},"analyst":{"role":"ANALYST","screenTitle":"Custody Intervals - Pattern Analysis","dataPayload":"INTERVAL ANALYSIS. For every entry, released minus received is uniform: each interval is a single minute, and the blank slot spans the same single minute. A number that had merely been skipped would leave no minute behind. An interval that had been covered over would show minutes accumulating. Measure the run before you decide.","visualType":"document-forensics","whatTheySee":"An analysis showing every custody interval is the same single minute.","taskPrompt":"Decide whether the blank slot is a clerical skip, a deletion, or a transfer that was never filed. Then read the number the run steps over.","intermediateOutput":"The blank slot holds a single minute like every other entry, so a transfer happened there; the run steps over exactly one successor to 16."},"operator":{"role":"OPERATOR","screenTitle":"Custody and Redaction Register","dataPayload":"CUSTODY AND REDACTION REGISTER. The register records every removal under a REDACTION CODE; a search for a redaction against this board returns none. The register also fixes the board numbering as strictly sequential, and no number may be reused. Enter the entry number that belongs in the blank slot.","visualType":"meta","whatTheySee":"A register with no redaction against the board and a strict sequential numbering rule.","taskPrompt":"Enter the entry number for the blank slot.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The custody and redaction register: it holds no REDACTION CODE for this board, so nothing was deleted, and it fixes the numbering as strictly sequential so no number was reused or skipped. That is what makes the blank slot a real, unfiled transfer.","operatorTaskDescription":"Hold the custody and redaction register. Only the Operator can run the redaction search and read the numbering rule, so the team must settle what the blank slot is before you type. Report the empty redaction search yourself; it is your own finding, not a restatement."},"coordinationChain":{"observerProduces":"The Observer reports the numbered run and the blank slot.","analystTransforms":"The Analyst measures the intervals and shows the blank slot holds the same single minute as a real transfer.","operatorExecutes":"The Operator, whose register shows no deletion and a strict sequence, enters the entry number for the blank slot."},"hints":["One slot in the numbered run is empty. Establish what the run and the intervals prove before you decide what happened to the record.","Measure received against released for every entry. The intervals do not scatter - they are all the same length.","The blank slot shows the same single minute as every other entry, so a transfer happened there; the numbering is strictly sequential, so the slot is the one number the run steps over."],"narrativeObjective":"Decide what the blank slot is before reading its number.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"17","validationMethod":"exact","fullSolution":"Every custody interval on the board is a single minute, so the blank slot held a real transfer rather than a skipped number or a covered-over gap, and the redaction register shows no deletion. The strict sequence makes the slot the entry number 17."}',
  metadata = '{"type":"LOGIC","difficulty":3,"time":"8m","storyReveal":"The custody board intervals are uniform to the minute, and one transfer in the run was never filed. The same single minute recurs wherever the programme records touch custody.","locationClue":{"format":"Color Code","clueText":"LINA''S NOTE: \"Find the blue-marked door in the corridor. It was hidden behind a tapestry.\"","solution":"Blue-Marked Door","nextPhysicalLocation":"[ADMIN BUILDING] - Blue-Marked Door","nextQrNode":"QR-NODE-10","explanation":"Points to the blue-marked door."},"evidenceUnlocked":{"id":"EVID-P09","category":"Document","title":"Custody Board Chronology (Extract)","state":"RECOVERED","timestamp":"Stage 2","source":"Clock room custody board","content":"Transfers listed in a numbered run with uniform single-minute custody intervals and one slot left unfiled. No deletion is recorded against the board."},"whyTeamworkMatters":"Only the board shows the run and the blank slot; only the interval analysis shows a transfer occurred; only the redaction register shows nothing was deleted.","feeds":"P08"}'
WHERE code = 'P09';

-- P10 The Blue Door - Stage 2 (a Bureau evidence class, recovered at the first lock)
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Blue Door - Marking Record","dataPayload":"BLUE-MARKED DOOR. A blue band runs across the door. It is not a hazard strip: it carries a stamped class glyph and the word AMBIENT, and it wraps around the frame onto the corridor wall. Elsewhere in the corridor the same blue band sits on stored exhibit boxes.","visualType":"observation","whatTheySee":"A blue band with a class glyph and the word AMBIENT, repeated on stored exhibit boxes.","taskPrompt":"Record the band, its stamp, and everywhere the same blue appears.","intermediateOutput":"A blue class band marked AMBIENT, repeated on archived exhibit boxes along the same corridor."},"analyst":{"role":"ANALYST","screenTitle":"Exhibit Tags - Class Comparison","dataPayload":"EXHIBIT TAGS IN THE ARCHIVE STORE carry the same blue band, and the band travels with the object into storage. A warning band would stop at the hazard and would not follow a box into a pale store. An aesthetic choice would not be repeated on stored boxes. Match the band class glyph against the five Stage-1 custody annotations: it is the class the first lock recovered.","visualType":"document-forensics","whatTheySee":"A comparison showing the same blue band on archived exhibit boxes and on the first lock annotations.","taskPrompt":"Decide whether the band is a warning, an aesthetic, or an evidence class, and name the class the first lock recovered.","intermediateOutput":"The band is a Bureau evidence class; the same class was recovered at the first lock."},"operator":{"role":"OPERATOR","screenTitle":"Bureau Classification Register","dataPayload":"BUREAU CLASSIFICATION REGISTER. Blue bands are class tokens for items observed under ambient conditions; the register refuses a warning label and refuses an aesthetic label for a blue band. Enter the class token the first lock recovered.","visualType":"meta","whatTheySee":"A register that classes blue bands as evidence tokens and refuses warning or aesthetic labels.","taskPrompt":"Enter the class token.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The Bureau classification register: it classes blue bands as tokens for items observed under ambient conditions, and it refuses both a warning label and an aesthetic label for a blue band. That refusal is what makes the marking a class rather than a caution or a decoration.","operatorTaskDescription":"Hold the Bureau classification register. It admits class tokens and rejects warning and aesthetic labels, so the team must agree on the kind of marking before you type. The class word itself comes from what the team recovered at the first lock, not from any field on this screen."},"coordinationChain":{"observerProduces":"The Observer reports the blue band, its class glyph, its AMBIENT mark, and where the same blue recurs.","analystTransforms":"The Analyst matches the band glyph to the Stage-1 custody class and shows the band travels with stored objects.","operatorExecutes":"The Operator, whose register admits class tokens alone, enters the class recovered at the first lock."},"hints":["Three readings fit a blue band: a warning, an aesthetic, a class. Check where else the same blue appears before choosing.","The same blue sits on archived exhibit boxes, so it travels with stored objects. A warning stops at the hazard, and an aesthetic would not follow a box into a store.","It is a Bureau class, and it is the class your first lock recovered: blue marks items observed under ambient conditions. Name that class."],"narrativeObjective":"Decide what kind of marking the blue band is before naming its class.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"LIGHT","validationMethod":"case_insensitive","fullSolution":"The band recurs on archived exhibit boxes and matches the class recovered at the first lock, so it is a Bureau evidence class rather than a warning or an aesthetic. The class for items observed under ambient conditions is LIGHT."}',
  metadata = '{"type":"EXTRACTION","difficulty":3,"time":"6m","storyReveal":"The blue marking is a Bureau evidence class, and it is the class the first lock recovered. The sealed room was processed as evidence before the programme vanished, so the Bureau catalogued what was inside.","locationClue":{"format":"Symbol Key","clueText":"LINA''S NOTE: \"Look at the wall. One symbol glows blue above the door.\"","solution":"Glowing Blue Symbol","nextPhysicalLocation":"[ADMIN BUILDING] - Wall with Glowing Blue Symbol","nextQrNode":"QR-NODE-11","explanation":"Points to a wall with a glowing blue symbol."},"evidenceUnlocked":{"id":"EVID-P10","category":"Visual","title":"Exhibit Tag - Blue Class","state":"RECOVERED","timestamp":"Stage 2","source":"Archive store","content":"A blue exhibit tag from the archive store carrying the same class glyph as the door band; the class covers items observed under ambient conditions."},"whyTeamworkMatters":"Only the door shows the band and its reach; only the archive tags show the band travels with stored objects; only the register classes blue as an evidence token.","feeds":"P09"}'
WHERE code = 'P10';

-- P11 The Symbol - Stage 2 (the scheme structure mark, a depiction, not a signature)
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Wall Glyph - Shape Record","dataPayload":"WALL ABOVE A DOORWAY. A stone glyph is mounted over the door: a curved span resting on two short legs, shaped like the opening beneath it. The stone is old and matches the blocks of the doorway itself.","visualType":"observation","whatTheySee":"A stone glyph shaped like a curved span on two legs, mounted above a doorway.","taskPrompt":"Record the glyph shape and what it is shaped like.","intermediateOutput":"A curved span on two legs, shaped like the opening beneath it."},"analyst":{"role":"ANALYST","screenTitle":"Glyph Scheme - Shape Comparison","dataPayload":"GLYPH SCHEME, recovered from the lab. The structure glyph of the scheme is the same shape: a span on two legs. A signature would be a personal hand, not a repeated scheme shape. A containment glyph would carry a bound or a ring, which this mark lacks. The scheme files its marks by what each one depicts.","visualType":"document-forensics","whatTheySee":"A scheme whose structure glyph has the same span-on-two-legs shape.","taskPrompt":"Decide whether the mark is decoration, a signature, or a containment symbol, and identify what its shape depicts.","intermediateOutput":"The mark is the structure glyph of the scheme; its shape depicts the curved span over the door."},"operator":{"role":"OPERATOR","screenTitle":"Glyph Register","dataPayload":"GLYPH REGISTER. The register files the seven marks by what each one depicts; the operator may confer the depicted feature and nothing else. Enter the feature this mark depicts.","visualType":"meta","whatTheySee":"A register that files glyphs by what they depict.","taskPrompt":"Enter the depicted feature.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The glyph register: it files the seven marks by what each one depicts and admits only a depicted feature, not a colour word and not a proprietary name. That filing rule is what turns the wall mark into a plain description of the opening it stands over.","operatorTaskDescription":"Hold the glyph register. It admits the depicted feature and nothing else, so the team must agree that the mark is the structure glyph before you type. The feature word is the plain name of the shape, drawn from the doorway itself."},"coordinationChain":{"observerProduces":"The Observer reports the glyph shape and the opening it is mounted over.","analystTransforms":"The Analyst matches the shape to the scheme structure glyph and rules out the signature and containment readings.","operatorExecutes":"The Operator, whose register files marks by what they depict, enters the depicted feature."},"hints":["The glyph shape is not arbitrary. Read it as a picture of something in the room before you read it as a mark.","A signature would be a personal hand; a containment mark would carry a bound. This shape repeats in the glyph scheme, so test it against the seven.","It matches the structure glyph of the scheme, and the scheme files marks by what they depict: this one depicts the curved stone span over a door. Name that feature."],"narrativeObjective":"Identify what the wall mark is and what its shape depicts.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"ARCHWAY","validationMethod":"case_insensitive","fullSolution":"The mark repeats the structure glyph of the scheme and lacks the bound of a containment mark, so it is a classification rather than graffiti. The scheme files marks by what they depict, and this one depicts the curved span over a door: an ARCHWAY."}',
  metadata = '{"type":"VISUAL","difficulty":3,"time":"7m","storyReveal":"The wall glyph is not graffiti: it is the scheme structure mark, mounted on the very feature it depicts. The programme marked its own doors with the classification of how each room held its subject.","locationClue":{"format":"Room Number","clueText":"LINA''S NOTE: \"Room 214 - the old lecture hall. Seats face forward. Look at the armrest of the marked seat.\"","solution":"Lecture Hall Room 214","nextPhysicalLocation":"[ADMIN BUILDING] - Lecture Hall 214","nextQrNode":"QR-NODE-12","explanation":"Points to Lecture Hall Room 214."},"evidenceUnlocked":{"id":"EVID-P11","category":"Document","title":"Lecture Hall 214 Seating Chart (2021)","state":"RECOVERED","timestamp":"Stage 2","source":"Lecture hall doorway","content":"A seating chart with one seat marked in the hand of L. Veyr and a note to check the armrest."},"whyTeamworkMatters":"Only the wall shows the glyph and its shape; only the scheme says the shape is the structure mark; only the register files marks by what they depict.","feeds":"P10"}'
WHERE code = 'P11';

-- P12 The Armrest - Stage 2 (a specimen accession, not merely a seat)
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Armrest - Mark Record","dataPayload":"LECTURE HALL 214, one armrest. Two marks are engraved on it. The first is a seat mark in the style of the hall: it reads ROW B, POSITION 7. The second is smaller and has a different provenance, a laboratory accession stamp from the Science Building, carrying the same row-and-position value.","visualType":"observation","whatTheySee":"An armrest with a hall seat mark and a laboratory accession stamp carrying the same row-and-position value.","taskPrompt":"Record both marks exactly, and note that they share one value but come from different places.","intermediateOutput":"Row B, position 7, struck once as a seat mark and once as a laboratory accession stamp."},"analyst":{"role":"ANALYST","screenTitle":"Specimen Register - Format Comparison","dataPayload":"SPECIMEN REGISTER, Science Building. Accessions are keyed by row letter and position: rows are lettered from A and positions are numbered from 1. The register lists accessions A3 and C2, and one accession in ROW B at POSITION 7 that is flagged. The lecture hall seating chart is a furniture record; the specimen register is the accession instrument.","visualType":"document-forensics","whatTheySee":"A specimen register using the same row-and-position format as the seating chart.","taskPrompt":"Decide which register the armrest value belongs to, and write the value the way an accession is written.","intermediateOutput":"The value is an accession in the specimen register, written row letter plus position with no space."},"operator":{"role":"OPERATOR","screenTitle":"Lab Accession Ledger","dataPayload":"LAB ACCESSION LEDGER. Only the Operator may confer an accession code; the seating chart of a lecture hall is not an accession instrument. The ledger writes an accession unspaced: row letter then position. Enter the accession code.","visualType":"meta","whatTheySee":"A ledger that confers unspaced accession codes by row letter and position.","taskPrompt":"Enter the accession code.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The lab accession ledger: it is the only instrument that confers an accession code, it refuses the lecture hall seating chart as a furniture record, and it writes an accession unspaced as row letter then position. That authority is what makes the armrest mark a specimen code rather than a seat number.","operatorTaskDescription":"Hold the lab accession ledger. It admits an unspaced accession and rejects a seat reading, so the team must agree which register the mark belongs to before you type. The row letter and the position come from the Observer mark, not from this screen."},"coordinationChain":{"observerProduces":"The Observer reports the seat mark and the accession stamp and the row-and-position value they share.","analystTransforms":"The Analyst matches the value to the Science Building specimen register and its unspaced row-and-position format.","operatorExecutes":"The Operator, whose ledger confers accessions alone, enters the unspaced accession code."},"hints":["Two marks share one value on the armrest. A seat and a specimen accession are different kinds of thing; decide which register this value belongs to.","The hall seating chart is a furniture record. The Science Building keeps a specimen register in the same row-and-position format - check it.","The value is an accession in the lab ledger, and the ledger writes it unspaced. Convert the armrest row letter and position into that form."],"narrativeObjective":"Decide which register the armrest value belongs to before writing it.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"B7","validationMethod":"exact","fullSolution":"The armrest carries a seat mark and a Science Building accession stamp with the same value. The specimen register, not the furniture chart, is the accession instrument, and the ledger writes accessions unspaced as row letter then position: B7."}',
  metadata = '{"type":"DEDUCTION","difficulty":3,"time":"6m","storyReveal":"The mark on the armrest is a laboratory accession, not a seat: the programme specimen register used the lecture hall own row-and-position scheme as cover, so a subject accession reads as a seat number.","locationClue":{"format":"Research-Note","clueText":"LINA''S NOTE: \"Under the seat is a keycard. It opens the Research Lab in the Science Building.\"","solution":"Science Building Research Lab","nextPhysicalLocation":"[SCIENCE BUILDING] - Research Lab","nextQrNode":"QR-NODE-13","explanation":"Points to the Science Building research lab."},"evidenceUnlocked":{"id":"EVID-P12","category":"Physical","title":"Keycard - Level 3 Access","state":"RECOVERED","timestamp":"Stage 2","source":"Under the armrest","content":"A keycard marked LEVEL 3 - RESEARCH DIVISION. It opens the Science Building research labs."},"whyTeamworkMatters":"Only the armrest shows both marks; only the specimen register gives the accession format; only the ledger holds the authority to confer an accession code.","feeds":"P11"}'
