-- P13 The Laboratory - Stage 2 (the office case file pulled to match the exhibits)
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Pull Slips - Field Record","dataPayload":"RESEARCH LAB, evidence shelf. A bundle of archive pull-slips is taped beside an empty binder slot. Every slip names the same three-part location: BINDER 34, SHELF 2, FILE 5. Each slip carries a pull date stamped in the corner. The slot itself is empty; the binder is out. The stamps rise in sequence and the most recent is dated yesterday.","visualType":"observation","whatTheySee":"A bundle of pull-slips all naming binder 34, shelf 2, file 5, each stamped with a pull date; the slot is empty.","taskPrompt":"Record the three-part location on the slips and the run of pull dates exactly as stamped.","intermediateOutput":"One binder location repeated on every slip; the pull stamps rise to yesterday; the shelf slot is empty."},"analyst":{"role":"ANALYST","screenTitle":"Pull Dates - Exhibit Comparison","dataPayload":"REQUISITION SHEET. A pull-slip is raised only when a filed item is matched to an object already in custody: one pull per filed exhibit. Line the pull dates against the Stage-2 exhibit recovery stamps. Every exhibit has exactly one pull, dated the day that exhibit was recovered. A theft would leave pulls with no matching exhibit. A routine audit would sweep its pulls onto a single day. Neither pattern is here.","visualType":"document-forensics","whatTheySee":"A requisition sheet showing exactly one pull per recovered exhibit, each dated to its recovery.","taskPrompt":"Decide whether the repeated pulls are a theft, a routine audit, or the office keeping its own file current. Then state what each pull is tied to.","intermediateOutput":"The pulls are not theft and not an audit; each pull is tied to exactly one recovered exhibit, so the office is filing its own case."},"operator":{"role":"OPERATOR","screenTitle":"Custody Register - File Recall","dataPayload":"CUSTODY REGISTER. The register records every pull and every return, and shows this binder is always returned to the same filing department within the day. That department is the office that owns the file, not an outside party. The binder slot demands the three-part location run together as one key: binder number, then shelf number, then file number, with nothing between them. Enter the key.","visualType":"meta","whatTheySee":"A register showing the binder is returned to its owning department, and a slot demanding the three-part location as one key.","taskPrompt":"Enter the three-part location as one key, binder then shelf then file.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The custody register: it shows every pull matched by a same-day return to the department that owns the file, so no outside party ever held the binder. That is what rules out theft and audit and makes the repeated pulls the office''s own filing.","operatorTaskDescription":"Hold the custody register. It proves the binder never left the department that owns it, so the team must agree the pulls are the office matching its exhibits. The slot takes the three-part location as a single key, binder first, then shelf, then file, with nothing between the numbers."},"coordinationChain":{"observerProduces":"The Observer reports the three-part location on the slips and the run of pull dates.","analystTransforms":"The Analyst lines the pull dates against the exhibits and rules out theft and audit, finding one pull per recovered exhibit.","operatorExecutes":"The Operator, from the custody register, confirms the binder is the office''s own and enters the three-part location as one key."},"hints":["The empty slot matters less than the slips. Ask what would leave one pull behind for every object the team has recovered.","A theft leaves pulls with no exhibit to match; an audit sweeps its pulls onto one day. These pulls each sit on a different day and each has exactly one exhibit, so neither reading survives.","The register shows the binder was always returned to the department that owns it, so the file is the office''s own case file, kept current as exhibits come in. The slot wants the three-part location run together, binder then shelf then file."],"narrativeObjective":"Identify why the programme case file is pulled from the archive again and again, and what the repeated location resolves to.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"3425","validationMethod":"exact","fullSolution":"Every pull-slip names the same binder location and each pull is dated the day one exhibit was recovered, so the pulls are the office keeping its own case file current rather than a theft or an audit. Run the three parts together - binder 34, shelf 2, file 5 - for 3425."}',
  metadata = '{"type":"OBSERVATION","difficulty":4,"time":"10m","storyReveal":"The programme file is not being stolen and not being audited: the office that owns it pulls and returns it once for each exhibit the team recovers, so the case file is being rebuilt in step with the investigation. Its shelf location is the first thing that must be read as one key rather than three numbers.","locationClue":{"format":"Symbol","clueText":"LINA''S NOTE: \"Inside the lab, find the symbol drawer. The second glyph is marked with a star.\"","solution":"Lab Symbol Drawer","nextPhysicalLocation":"[SCIENCE BUILDING] - Lab Symbol Drawer","nextQrNode":"QR-NODE-14","explanation":"Points to the lab symbol drawer."},"evidenceUnlocked":{"id":"EVID-P13","category":"Document","title":"Lab Symbol Drawer - Glyph Key","state":"RECOVERED","timestamp":"Stage 2","source":"Research lab symbol drawer","content":"A key mapping seven symbols to conceptual names. The second, marked with a star, is named Connection. The key lists Origin, Connection, Structure, Memory, Choice, Truth, Finality in order."},"whyTeamworkMatters":"Only the slips show the repeated three-part location and the pull dates; only the exhibit comparison shows one pull per recovered exhibit; only the custody register shows the binder never left its owning department.","feeds":"P12"}'
