-- P06b Time Remaining - Stage 2 (a session duration in whole minutes, not a countdown or a time of day)
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Lab Clock - Dial Record","dataPayload":"SCIENCE BUILDING, instrument bench. A lab clock is bolted above the bench; its face has been repainted and its hand is fixed. Below it hangs a session card headed SESSION DURATION with one field filled in by hand in the older roman style: XVII. A smaller line beneath reads: THIS LAB RECORDS SESSIONS, NOT THE TIME OF DAY.","visualType":"observation","whatTheySee":"A fixed lab clock with a session card whose one filled field is a roman numeral in the older style.","taskPrompt":"Record the numeral exactly as written and the line about what this lab records.","intermediateOutput":"A session-duration field stamped XVII; the card states the lab records sessions, not times of day."},"analyst":{"role":"ANALYST","screenTitle":"Session Log - Duration Convention","dataPayload":"SESSION LOG, first page. The log header states its convention: every session is stored as a single whole number of MINUTES. There is no hour column and no hour-and-minute field anywhere in the log. A countdown would tick and would need a start mark; this card carries none. A fixed clock reads the time of day; this card is not a clock face. Only a plain count of minutes is stored.","visualType":"document-forensics","whatTheySee":"A log convention that stores sessions as a single whole number of minutes and has no clock field.","taskPrompt":"Decide whether the field is a countdown, a time of day, or a duration, and give the unit the log uses. Then convert the old-style numeral to the log notation.","intermediateOutput":"The field is a session duration in whole minutes, not a countdown or a time of day; the log writes it as one plain number."},"operator":{"role":"OPERATOR","screenTitle":"Instrument Bench - Session Authorisation","dataPayload":"INSTRUMENT BENCH. The bench sets only a whole-minute session duration; it accepts no clock reading, which is why the wall clock hand is fixed. The stamp is in the older roman style, the same style the team already converted earlier in the archive. Enter the session duration as whole minutes.","visualType":"meta","whatTheySee":"A bench that sets only whole-minute durations.","taskPrompt":"Enter the session duration in whole minutes.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The instrument bench: it sets a session only as a whole number of minutes and refuses any clock reading, which is why the wall clock hand is fixed. That is the third member of the team confirming the unit before the numeral is converted.","operatorTaskDescription":"Hold the instrument bench. It takes whole minutes only, so the team must call the field a duration and not a countdown and not a time of day. The numeral is in the same older style the archive used, and the log wants it as one plain number of minutes."},"coordinationChain":{"observerProduces":"The Observer reports the roman-style field and the card line that this lab records sessions.","analystTransforms":"The Analyst reads the log convention, rules out a countdown and a time of day, and names the unit as whole minutes.","operatorExecutes":"The Operator, whose bench accepts only whole-minute durations, enters the converted numeral as a plain count of minutes."},"hints":["A countdown runs; a clock face reads the hour. Look at what this field is stamped on before you decide which it is.","The log has no hour column and no hour-and-minute field. Every session it stores is one whole number of minutes, so the field is a duration and the unit is minutes.","The card is a session duration and the log writes durations in whole minutes; the stamp is in the same older numeral style the archive already gave the team. Convert it and enter it as a plain number of minutes."],"narrativeObjective":"Determine what the lab session card field measures - a countdown, a time of day, or a duration - and convert it to the notation the lab log uses.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"17","validationMethod":"exact","fullSolution":"The log stores every session as a single whole number of minutes and carries no clock field, so the stamped field is a duration rather than a countdown or a time of day. Converting the older numeral XVII to the log''s plain number of minutes gives 17."}',
  metadata = '{"type":"MEMORY","difficulty":1,"time":"3m","storyReveal":"The lab recorded its work not by when a session happened but by how long it ran, and every run was a whole number of minutes. The duration is the same value the archive already returned, so the programme measured its subjects in whole units it had used before.","locationClue":{"format":"Symbol","clueText":"LINA''S NOTE: \"The symbol drawer is open. Take the glyph key.\"","solution":"Open Symbol Drawer","nextPhysicalLocation":"[SCIENCE BUILDING] - Open Symbol Drawer","nextQrNode":"QR-NODE-15","explanation":"Points to the open symbol drawer."},"evidenceUnlocked":{"id":"EVID-P06b","category":"Document","title":"Lab Instrument Log - Session Durations","state":"RECOVERED","timestamp":"Stage 2","source":"Lab instrument bench","content":"A lab instrument log whose header stores every session as a single whole number of minutes; one session card carries its duration in an older numeral style. The log holds no hour column and no clock field."},"whyTeamworkMatters":"Only the card shows the old-style field and the session line; only the log gives the whole-minute convention; only the bench confirms the unit by refusing a clock reading.","feeds":"P13"}'
WHERE code = 'P06b';

-- P07b The Network - Stage 2 (a subject plot, not a power grid or a rank tree)
-- The accepted answer is recovered cross-gate from the glyph key evidence
-- unlocked at P13, which names the starred second mark. It is never written
-- in this gate's own strings.
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Basement Wall Plot - Field Record","dataPayload":"BASEMENT ARCHIVE, lower wall. A plot is inked straight onto the plaster, taller than the doorway beside it. THREE marks sit inside painted rings: the origin mark, the starred mark, and the structure mark. DRAWN LINES run between them, origin to starred and starred to structure, with nothing skipping the middle. A paper LEGEND strip is pasted along the bottom edge. Most of it is torn away; one line survives and is still legible: AN EDGE IS A PERSON.","visualType":"graph-network","whatTheySee":"A wall plot of three ringed marks joined in a line, with a torn legend strip whose surviving line reads: an edge is a person.","taskPrompt":"Record the three marks in the order the lines run, and quote the surviving legend line word for word.","intermediateOutput":"Three ringed marks - origin, starred, structure - joined in running order with no line skipping the middle; the surviving legend line reads: an edge is a person."},"analyst":{"role":"ANALYST","screenTitle":"Survey Card File - Plot Types","dataPayload":"SURVEY CARD FILE, this level. The surveyors kept three plot types, each with its own legend convention. A POWER PLOT rings rooms and its legend gives voltages. A RANK PLOT rings posts and its legend gives seniority lines; it always rises from one root post, so one mark would sit above the rest. A SUBJECT PLOT rings filed items and its legend gives persons, because it records who was bound to whom. No room on this level was ever ringed twice, and no post hierarchy was ever surveyed here. The one legend line this plot still carries is about persons.","visualType":"document-forensics","whatTheySee":"Three plot-type cards, each naming what its marks ring and what its legend gives.","taskPrompt":"Decide which plot type this wall carries - power, rank, or subject - from what is ringed and what the surviving legend line gives.","intermediateOutput":"The marks ring filed items rather than rooms or posts, and the surviving legend line gives persons, so the wall carries a subject plot."},"operator":{"role":"OPERATOR","screenTitle":"Archive Console - Mark Name","dataPayload":"ARCHIVE CONSOLE, beneath the plot. The console takes one word and its prompt reads: NAME THE MARK AT THE CENTRE. The name is not written anywhere on this level: the plot carries marks but not their names, and the torn legend names a relation, not a mark. The names were filed upstairs, on the drawer card the team recovered in the research lab. The console takes the name exactly as that card writes it, one word, ten letters.","visualType":"meta","whatTheySee":"A console demanding the central mark''s name in one word, which this level does not carry.","taskPrompt":"Enter the name the lab drawer card gives the starred mark, spelled as the card writes it.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The archive console: it accepts only the one word the lab drawer card writes for the starred mark, and it refuses the mark''s shape, its position in the run, and the surviving legend line as entries. The plot''s own legend line says what an edge is; the mark''s name was filed upstairs.","operatorTaskDescription":"Hold the archive console. The plot gives the marks and one legend line but no names, so the team must take the central mark''s name from the drawer card recovered in the research lab - the card that names all seven marks in filing order."},"coordinationChain":{"observerProduces":"The Observer records the three ringed marks in running order and the surviving legend line: an edge is a person.","analystTransforms":"The Analyst rules out a power plot and a rank plot from what is ringed and what the legend line gives, leaving a subject plot.","operatorExecutes":"The Operator enters the starred mark''s name as the lab drawer card writes it, which only the card filed upstairs can supply."},"hints":["The marks are the same seven the research lab drawer card names, and that card is on the team board.","The star sits on the middle mark, and the card names its marks in filing order; the starred one is the second entry.","The console wants that entry in one word, ten letters, spelled as the card writes it. Neither the mark''s shape nor the legend line will be accepted."],"narrativeObjective":"Establish what kind of plot the basement wall carries, and recover the name the drawer card gives its starred mark.","roleDependencyLevel":"D3"}',
  answer_metadata = '{"acceptedAnswer":"CONNECTION","validationMethod":"case_insensitive","fullSolution":"The surviving legend line defines an edge as a person, which neither a power plot - its legend gives voltages - nor a rank plot - it would rise from one root post - would print, so the wall carries a subject plot. The ringed marks are the lab scheme, and its starred second entry is CONNECTION."}',
  metadata = '{"type":"GRAPH","difficulty":4,"time":"9m","storyReveal":"The basement wall is not infrastructure and not a hierarchy: it is a subject plot, ringed over filed items with a legend that gives persons, so the archive mapped how people were bound to one another before it mapped a single room. The mark at the centre of the plot carries the scheme''s second name.","locationClue":{"format":"Path Instruction","clueText":"LINA''S NOTE: \"Take the staircase down. Three flights. Stop at the bottom.\"","solution":"Basement Archive Level","nextPhysicalLocation":"[SCIENCE BUILDING] - Basement Archive","nextQrNode":"QR-NODE-16","explanation":"Points to the basement archive level."},"evidenceUnlocked":{"id":"FRAG-02","category":"Symbol Fragment","title":"Fragment 2 - Lattice","state":"RECOVERED","timestamp":"Stage 2","source":"Basement archive locker","content":"The second fragment. The word LATTICE appears: \"The grid is the map. The lines connect the dots. Follow the lattice.\""},"whyTeamworkMatters":"Only the wall shows the plot and its surviving legend line; only the survey card file says which plot types this building used; only the drawer card filed upstairs carries the starred mark''s name.","feeds":"P06b"}'
WHERE code = 'P07b';

-- M02 The Network Meta - Stage 2 (one running chain of bindings, not a coincidence or a stamp quirk)
-- The accepted answer is recovered cross-gate from the same glyph key evidence
-- (P13). The seven values listed on the panel are other gates' answers; that is
-- legal. This gate's own answer never appears in its strings.
UPDATE puzzle_nodes SET
  content = '{"observer":{"role":"OBSERVER","screenTitle":"Convergence Panel - Row Record","dataPayload":"BASEMENT TRANSFER CHAMBER, beside the door. A steel panel is ruled into eight numbered rows, each with a HEADING field and a VALUE field, filled in the Bureau''s hand. 01 PIVOT CARD - 17. 02 RACK TAPE - 17:47. 03 VAULT PLATE - DELTA. 04 DOOR CLASS - LIGHT. 05 WALL MARK - ARCHWAY. 06 ACCESSION - B7. 07 PULL SLIPS - 3425. 08 BONDS FILED - the value field is BLANK, and the terminal beside the panel is lit.","visualType":"meta","whatTheySee":"An eight-row panel listing every Stage-2 recovery; the eighth row is headed BONDS FILED and its value field is blank.","taskPrompt":"Read the seven filled rows in order, then read the eighth heading exactly as written.","intermediateOutput":"Seven filled rows naming the team''s recoveries; the eighth row is headed BONDS FILED with a blank value field and a lit terminal."},"analyst":{"role":"ANALYST","screenTitle":"Chain Test - Row Analysis","dataPayload":"CHAIN TEST. For each row, name the record that produced the value and the record that read it. 01: the pivot card produced a heading the subject register read. 02: the rack tape produced a stamp the rack console read. 03: the vault plate produced a mark the corridor index read. Then through the door class, the wall mark, the accession and the slips: every row binds exactly one source record to exactly one reading record, and each reading is the next row''s source. A coincidence would leave rows binding nothing; a filing quirk would bind every row to the same stamp. This binds seven pairs in running order, and the panel kept its eighth row for one more entry of the same family - the name of the thing every row files.","visualType":"document-forensics","whatTheySee":"A chain test showing each row binds a source record to a reading record, and each reading seeds the next row.","taskPrompt":"Decide whether the rows are coincidence, a filing quirk, or one running chain of bindings. Then say what the blank eighth row asks for.","intermediateOutput":"The rows bind seven pairs in running order with each reading seeding the next, so the stage is one running chain, and the eighth row asks for the name of what every row files."},"operator":{"role":"OPERATOR","screenTitle":"Panel Terminal - Bond Name","dataPayload":"PANEL TERMINAL. The terminal keys to one word and its prompt reads: NAME OF WHAT IS FILED. It refuses the seven values above it - each is one filed binding, not the name of filing - and it refuses the locker word from the fragments, which names the grid rather than the binding. One card the team recovered names every mark and every bond in filing order, and its starred entry is the family the rows belong to. The terminal takes that entry, one word, ten letters.","visualType":"meta","whatTheySee":"A terminal demanding the name of what is filed, refusing both the seven row values and the locker fragment word.","taskPrompt":"Enter the starred entry''s name from the lab drawer card, as the card writes it.","intermediateOutput":"Awaiting the team conclusion."},"operatorInvestigation":{"operatorOwnEvidence":"The panel terminal: it refuses every row value as a category error - each value is one binding, not the name of binding - and it refuses the locker word because the fragments name the grid, not the binding. Only the drawer card''s starred entry fits both the heading and the letter count.","operatorTaskDescription":"Hold the panel terminal. The rows must be read as a running chain rather than a coincidence or a stamp quirk, and the blank row wants the name of what every row files: the starred entry of the drawer card recovered in the research lab."},"coordinationChain":{"observerProduces":"The Observer reads the seven filled rows and the eighth heading, BONDS FILED, over a blank value field.","analystTransforms":"The Analyst runs the chain test, rules out coincidence and filing quirk, and finds every row binds a source record to a reading record.","operatorExecutes":"The Operator enters the drawer card''s starred entry - the family the rows belong to - at the panel terminal."},"hints":["Line each value up with the record that produced it and the record that read it. Ask what every row holds in common.","Coincidence binds nothing and a filing quirk binds every row to one stamp; these rows bind seven different pairs in running order, each reading seeding the next.","The blank row is headed BONDS FILED, and the drawer card''s starred entry names one binding in filing order. The locker fragments name the grid instead, so the card, not the fragments, is what the terminal will take."],"narrativeObjective":"Test whether the eight Stage-2 recoveries are coincidence, a filing quirk, or one running chain, and name what the blank row is waiting for.","roleDependencyLevel":"D4"}',
  answer_metadata = '{"acceptedAnswer":"CONNECTION","validationMethod":"case_insensitive","fullSolution":"Every row binds one source record to one reading record and each reading seeds the next, which neither a coincidence nor a shared-stamp filing quirk would produce: Stage 2 is one running chain of bindings. The blank row asks for the name of what is filed, and the drawer card''s starred entry names it: CONNECTION."}',
  metadata = '{"type":"META","difficulty":4,"time":"15m","storyReveal":"Stage 2 was one file all along: every recovery bound a source record to a reading record and each reading fed the next, and the chamber panel kept its eighth row waiting for the name of that binding. The programme did not collect exhibits; it ran a chain.","locationClue":{"format":"Path Instruction","clueText":"LINA''S NOTE: \"Enter the memory lab. The transfer chamber is in the basement.\"","solution":"Memory Transfer Chamber","nextPhysicalLocation":"[SCIENCE BUILDING] - Basement Transfer Chamber","nextQrNode":"QR-NODE-16","explanation":"Points to the memory transfer chamber."},"evidenceUnlocked":{"id":"FRAG-04","category":"Symbol Fragment","title":"Fragment 4 - Lattice","state":"RECOVERED","timestamp":"Stage 2","source":"Memory lab terminal","content":"The fourth fragment. The word LATTICE: \"The grid connects. The intersection is the node. Find the lattice.\""},"whyTeamworkMatters":"Only the panel shows the eight rows and the blank heading; only the chain test shows each value binds a source to a reading; only the drawer card carries the starred name the terminal will accept.","feeds":"P06 P07 P08 P09 P10 P11 P12 P13"}'
